/* ============================================================
   Modelo 3D realista do arbusto (GLB embutido em base64: nada para hospedar).
   Precisa só do THREE.GLTFLoader carregado. Se não existir, o arbusto continua com a moita antiga.
   Crédito do modelo (Sketchfab): "Photorealistic Bush" por Adrian Sheremet, licença CC BY 4.0
   ============================================================ */
const ArbustoGLB = (() => {
  const B64 = '';
  const ESCALA = 1;        // multiplicador de tamanho (o modelo tem ~1,5 de largura; cada arbusto varia de 0,7× a 1,3×)
  const MAX_REALISTAS = 30; // quantos arbustos usam o modelo realista; os demais ficam com a moita antiga (alivia a GPU)

  let gltf = null, carregando = false, falhou = false, usados = 0;
  const fila = [];

  const bytes = () => { const s = atob(B64), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u.buffer; };

  // Lê o arquivo uma vez; cada arbusto é um clone que compartilha malha e texturas.
  function pedir(ok, nok) {
    if (gltf) return ok(gltf);
    if (falhou) return nok();
    fila.push([ok, nok]);
    if (carregando) return;
    carregando = true;
    new THREE.GLTFLoader().parse(bytes(), '', g => { gltf = g; fila.splice(0).forEach(f => f[0](g)); },
      e => { console.warn('Arbusto (GLB):', e); falhou = true; fila.splice(0).forEach(f => f[1]()); });
  }

  function crescer(ctx, x, z, antigo) {
    if (!(window.THREE && THREE.GLTFLoader) || usados >= MAX_REALISTAS) return antigo();
    usados++;
    pedir(g => {
      const m = g.scene.clone(true), { scene, rnd } = ctx;
      m.position.set(x, 0, z); m.rotation.y = rnd(0, Math.PI * 2); m.scale.setScalar(ESCALA * rnd(.7, 1.3));
      m.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
      scene.add(m);
    }, antigo);
  }
  return { crescer };
})();

/* ============================================================
   Arbusto: tudo sobre esta planta fica nesta pasta.
   kind: 'bush' · moita baixa espalhada pelo chão
   grow(ctx, x, z) cria o modelo na posição (x, z) e devolve nada
   ============================================================ */
registerPlant('arbusto', {
  kind: 'bush',
  count: 30,   /* quantos tentar espalhar */

  grow(ctx, x, z) {
    const { scene, M, hsl, rnd, shade } = ctx;
    /* moita antiga: usada como reserva se o modelo realista não puder ser carregado */
    const antigo = () => {
      const b = new THREE.Mesh(new THREE.IcosahedronGeometry(rnd(.5, 1), 1), M(hsl(rnd(.25, .34), .5, rnd(.2, .3))));
      b.scale.y = .7; b.position.set(x, .4, z); shade(b); scene.add(b);
    };
    ArbustoGLB.crescer(ctx, x, z, antigo);   /* arbusto realista (GLB) */
  }
});
